create extension if not exists pgcrypto;
create table if not exists vehicles (id uuid primary key default gen_random_uuid(),vin text unique not null,serial_no text,model text,customer text,salesperson text,in_service_date date,source text,extra_fields jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists lookup_batches (id uuid primary key default gen_random_uuid(),lookup_mode text not null default 'in_service_customer',status text not null default 'queued',total_vins int not null default 0,options jsonb not null default '{}'::jsonb,worker_id text,created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz);
create table if not exists lookup_batch_items (id uuid primary key default gen_random_uuid(),batch_id uuid not null references lookup_batches(id) on delete cascade,vin text not null,queue_position int not null default 0,status text not null default 'queued',attempts int not null default 0,result jsonb not null default '{}'::jsonb,error_message text,started_at timestamptz,completed_at timestamptz,unique(batch_id,vin));
create index if not exists lookup_items_queue_idx on lookup_batch_items(batch_id,status,queue_position);
create table if not exists worker_status (worker_id text primary key,hostname text,dtna_status text,outlook_status text,onedrive_status text,master_workbook text,details jsonb not null default '{}'::jsonb,last_seen timestamptz not null default now());
create table if not exists worker_commands (id uuid primary key default gen_random_uuid(),command text not null,status text not null default 'queued',worker_id text,payload jsonb not null default '{}'::jsonb,result jsonb not null default '{}'::jsonb,error_message text,created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz);
create index if not exists worker_commands_queue_idx on worker_commands(status,created_at);
